{"model":"glm-4.7","tail_role":"tool","tail_preview":"1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Todo List 待办事项</title>
7	  <script src="https://cdn.tailwindcss.com"></script>
8	  <style>
9	    .task-item {
10	      transition: all 0.3s ease;
11	    }
12	    .task-item:hover {
13	      transform: translateX(4px);
14	    }
15	    .task-completed .task-text {
16	      text-decoration: line-through;
17	      color: #9ca3af;
18	    }
19	    .checkbox-custom {
20	      appearance: none;
21	      width: 24px;
22	      height: 24px;
23	      border: 2px solid #d1d5db;
24	      border-radius: 50%;
25	      cursor: pointer;
26	      transition: all 0.2s ease;
27	    }
28	    .checkbox-custom:checked {
29	      background-color: #10b981;
30	      border-color: #10b981;
31	    }
32	    .checkbox-custom:checked::after {
33	      content: '✓';
34	      display: flex;
35	      justify-content: center;
36	      align-items: center;
37	      color: white;
38	      font-size: 14px;
39	      font-weight: bold;
40	    }
41	  </style>
42	</head>
43	<body class="bg-gradient-to-br from-indigo-100 via-purple-50 to-pink-100 min-h-screen">
44	  <div class="max-w-2xl mx-auto px-4 py-12">
45	    <!-- 标题区域 -->
46	    <div class="text-center mb-8">
47	      <h1 class="text-4xl font-bold text-gray-800 mb-2">📝 Todo List</h1>
48	      <p class="text-gray-600">高效管理你的待办事项</p>
49	    </div>
50	
51	    <!-- 统计信息 -->
52	    <div class="bg-white rounded-2xl shadow-lg p-6 mb-6">
53	      <div class="flex justify-around text-center">
54	        <div>
55	          <p class="text-3xl font-bold text-indigo-600" id="totalTasks">0</p>
56	          <p class="text-sm text-gray-500">总任务</p>
57	        </div>
58	        <div>
59	          <p class="text-3xl font-bold text-yellow-600" id="pendingTasks">0</p>
60	          <p class="text-sm text-gray-500">待完成</p>
61	        </div>
62	        <div>
63	          <p class="text-3xl font-bold text-green-600" id="completedTasks">0</p>
64	          <p class="text-sm text-gray-500">已完成</p>
65	        </div>
66	      </div>
67	    </div>
68	
69	    <!-- 添加任务输入框 -->
70	    <div class="bg-white rounded-2xl shadow-lg p-6 mb-6">
71	      <div class="flex gap-3">
72	        <input
73	          type="text"
74	          id="taskInput"
75	          placeholder="输入新任务..."
76	          class="flex-1 px-4 py-3 border-2 border-gray-200 rounded-xl focus:outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-200 transition-all"
77	          onkeypress="if(event.key === 'Enter') addTask()"
78	        >
79	        <button
80	          onclick="addTask()"
81	          class="px-6 py-3 bg-indigo-600 text-white rounded-xl font-semibold hover:bg-indigo-700 active:scale-95 transition-all shadow-md hover:shadow-lg"
82	        >
83	          添加
84	        </button>
85	      </div>
86	    </div>
87	
88	    <!-- 任务列表 -->
89	    <div class="bg-white rounded-2xl shadow-lg p-6">
90	      <div class="flex justify-between items-center mb-4">
91	        <h2 class="text-xl font-semibold text-gray-800">任务列表</h2>
92	        <button
93	          onclick="clearAll()"
94	          class="text-sm text-red-500 hover:text-red-700 hover:underline transition-all"
95	        >
96	          清空所有
97	        </button>
98	      </div>
99	
100	      <div id="taskList" class="space-y-3">
101	        <!-- 任务项将在这里动态生成 -->
102	      </div>
103	
104	      <div id="emptyState" class="text-center py-8 text-gray-400">
105	        <p class="text-5xl mb-3">📭</p>
106	        <p>暂无任务，添加一个吧！</p>
107	      </div>
108	    </div>
109	
110	    <!-- 页脚 -->
111	    <div class="text-center mt-8 text-gray-500 text-sm">
112	      <p>数据保存在本地浏览器中</p>
113	    </div>
114	  </div>
115	
116	  <script>
117	    // 从 localStorage 加载任务
118	    let tasks = JSON.parse(localStorage.getItem('todos')) || [];
119	
120	    // 初始化渲染
121	    renderTasks();
122	
123	    // 添加任务
124	    function addTask() {
125	      const input = document.getElementById('taskInput');
126	      const text = input.value.trim();
127	
128	      if (text === '') {
129	        alert('请输入任务内容！');
130	        return;
131	      }
132	
133	      const task = {
134	        id: Date.now(),
135	        text: text,
136	        completed: false,
137	        createdAt: new Date().toLocaleString('zh-CN')
138	      };
139	
140	      tasks.unshift(task);
141	      saveTasks();
142	      renderTasks();
143	      input.value = '';
144	    }
145	
146	    // 切换完成状态
147	    function toggleTask(id) {
148	      const task = tasks.find(t => t.id === id);
149	      if (task) {
150	        task.completed = !task.completed;
151	        saveTasks();
152	        renderTasks();
153	      }
154	    }
155	
156	    // 删除任务
157	    function deleteTask(id) {
158	      if (confirm('确定要删除这个任务吗？')) {
159	        tasks = tasks.filter(t => t.id !== id);
160	        saveTasks();
161	        renderTasks();
162	      }
163	    }
164	
165	    // 清空所有任务
166	    function clearAll() {
167	      if (tasks.length === 0) {
168	        alert('任务列表已经是空的！');
169	        return;
170	      }
171	
172	      if (confirm('确定要清空所有任务吗？此操作不可撤销！')) {
173	        tasks = [];
174	        saveTasks();
175	        renderTasks();
176	      }
177	    }
178	
179	    // 保存任务到 localStorage
180	    function saveTasks() {
181	      localStorage.setItem('todos', JSON.stringify(tasks));
182	    }
183	
184	    // 渲染任务列表
185	    function renderTasks() {
186	      const taskList = document.getElementById('taskList');
187	      const emptyState = document.getElementById('emptyState');
188	
189	      // 更新统计
190	      document.getElementById('totalTasks').textContent = tasks.length;
191	      document.getElementById('pendingTasks').textContent = tasks.filter(t => !t.completed).length;
192	      document.getElementById('completedTasks').textContent = tasks.filter(t => t.completed).length;
193	
194	      // 显示/隐藏空状态
195	      emptyState.style.display = tasks.length === 0 ? 'block' : 'none';
196	
197	      // 渲染任务项
198	      taskList.innerHTML = tasks.map(task => `
199	        <div class="task-item flex items-center gap-4 p-4 bg-gray-50 rounded-xl ${task.completed ? 'task-completed' : ''}">
200	          <input
201	            type="checkbox"
202	            class="checkbox-custom"
203	            ${task.completed ? 'checked' : ''}
204	            onchange="toggleTask(${task.id})"
205	          >
206	          <div class="flex-1">
207	            <p class="task-text font-medium text-gray-800">${escapeHtml(task.text)}</p>
208	            <p class="text-xs text-gray-400 mt-1">${task.createdAt}</p>
209	          </div>
210	          <button
211	            onclick="deleteTask(${task.id})"
212	            class="text-red-400 hover:text-red-600 hover:bg-red-50 p-2 rounded-lg transition-all"
213	            title="删除"
214	          >
215	            🗑️
216	          </button>
217	        </div>
218	      `).join('');
219	    }
220	
221	    // HTML 转义（防止 XSS）
222	    function escapeHtml(text) {
223	      const div = document.createElement('div');
224	      div.textContent = text;
225	      return div.innerHTML;
226	    }
227	  </script>
228	</body>
229	</html>
